#!/usr/bin/env python3
"""
Backfill script: adds the 6 default soundboard sounds (Ding, Pop, Chime, Buzz,
Boop, Whoosh) to every EXISTING user (personal/Detached soundboard) and every
EXISTING server (server soundboard) that doesn't already have them.

This is a ONE-OFF script, run manually, OUTSIDE the main Rust backend. It does
not touch the compose stack, the backend code, or any running container image
-- it only talks to Mongo (to read/write the soundboard_sounds collection and
list users/servers) and to Autumn (to upload the 6 audio files, authenticated
as the same system bot used by the backend's own auto-seeding hook).

SAFE TO RE-RUN: for every user/server, it first checks whether any of the 6
default sound names already exist for that owner; if so, it skips that owner
entirely. Running it twice will not create duplicates.

Requires env vars:
  MONGODB_URI   - same connection string used by the backend ([database] mongodb in Revolt.toml)
  MONGODB_NAME  - the database name (commonly "revolt")
  AUTUMN_BASE   - same base URL as settings.hosts.autumn in Revolt.toml (e.g. http://autumn:14702)
  BOT_TOKEN     - the system bot token (same one already in [soundboard] system_bot_token)

Requires: pip install pymongo requests
"""
import os
import sys
import time
import random
import base64
import requests
from pymongo import MongoClient

MONGODB_URI = os.environ["MONGODB_URI"]
MONGODB_NAME = os.environ.get("MONGODB_NAME", "revolt")
AUTUMN_BASE = os.environ["AUTUMN_BASE"].rstrip("/")
BOT_TOKEN = os.environ["BOT_TOKEN"]

DEFAULT_SOUNDS = [
    {"name": "Ding", "b64": ""},
    {"name": "Pop", "b64": ""},
    {"name": "Chime", "b64": ""},
    {"name": "Buzz", "b64": ""},
    {"name": "Boop", "b64": ""},
    {"name": "Whoosh", "b64": ""},

]
DEFAULT_NAMES = [s["name"] for s in DEFAULT_SOUNDS]

# --- Minimal ULID generator (26-char Crockford base32, time-sortable) ---
CROCKFORD = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"

def new_ulid():
    ms = int(time.time() * 1000)
    time_part = ""
    t = ms
    for _ in range(10):
        time_part = CROCKFORD[t % 32] + time_part
        t //= 32
    rand_part = "".join(random.choice(CROCKFORD) for _ in range(16))
    return time_part + rand_part

def upload_sound_to_autumn(b64_bytes, filename):
    raw = base64.b64decode(b64_bytes)
    resp = requests.post(
        f"{AUTUMN_BASE}/attachments",
        headers={"x-bot-token": BOT_TOKEN},
        files={"file": (filename, raw, "audio/wav")},
        timeout=30,
    )
    resp.raise_for_status()
    return resp.json()["id"]

def already_seeded(col, creator_id, parent_query):
    query = {"creator_id": creator_id, "name": {"$in": DEFAULT_NAMES}}
    query.update(parent_query)
    return col.find_one(query) is not None

def seed_for_owner(col, creator_id, parent_doc, parent_query, label):
    if already_seeded(col, creator_id, parent_query):
        print(f"  skip {label} (already has default sounds)")
        return 0
    created = 0
    for sound in DEFAULT_SOUNDS:
        try:
            file_id = upload_sound_to_autumn(sound["b64"], f"{sound['name'].lower()}.wav")
        except Exception as e:
            print(f"  WARN upload failed for {label} / {sound['name']}: {e}")
            continue
        doc = {
            "_id": new_ulid(),
            "parent": parent_doc,
            "creator_id": creator_id,
            "name": sound["name"],
            "emoji": None,
            "file_id": file_id,
            "volume": 100,
        }
        try:
            col.insert_one(doc)
            created += 1
        except Exception as e:
            print(f"  WARN insert failed for {label} / {sound['name']}: {e}")
    print(f"  {label}: added {created}/6 sounds")
    return created

def main():
    client = MongoClient(MONGODB_URI)
    db = client[MONGODB_NAME]
    col = db["soundboard_sounds"]
    users = db["users"]
    servers = db["servers"]

    print("=== Personal (Detached) soundboards for existing users ===")
    user_count = 0
    for user in users.find({}, {"_id": 1}):
        uid = user["_id"]
        seed_for_owner(
            col, uid,
            {"type": "Detached"},
            {"parent.type": "Detached"},
            f"user {uid}",
        )
        user_count += 1
    print(f"Processed {user_count} users.")

    print()
    print("=== Server soundboards for existing servers ===")
    server_count = 0
    for server in servers.find({}, {"_id": 1, "owner": 1}):
        sid = server["_id"]
        owner = server.get("owner", sid)
        seed_for_owner(
            col, owner,
            {"type": "Server", "id": sid},
            {"parent.type": "Server", "parent.id": sid},
            f"server {sid}",
        )
        server_count += 1
    print(f"Processed {server_count} servers.")

    print()
    print("Done.")

if __name__ == "__main__":
    main()
